const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Mount Fuji location
  const fuji = ee.Geometry.Point([138.73, 35.36]).buffer(5000); // 5km radius

  // Date ranges
  const date2019 = ['2019-12-01', '2019-12-31'];
  const date2020 = ['2020-12-01', '2020-12-31'];

  // Cloud masking function for Sentinel-2
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to calculate NDSI
  function addNDSI(image) {
    const ndsi = image.normalizedDifference(['B3', 'B11']).rename('NDSI');
    return image.addBands(ndsi);
  }

  // Get Sentinel-2 collections
  let col2019 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(fuji)
    .filterDate(date2019[0], date2019[1])
    .map(maskClouds)
    .map(addNDSI);

  let col2020 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(fuji)
    .filterDate(date2020[0], date2020[1])
    .map(maskClouds)
    .map(addNDSI);

  const size2019 = await col2019.size().getInfo();
  const size2020 = await col2020.size().getInfo();

  console.log(`2019 Images: ${size2019}`);
  console.log(`2020 Images: ${size2020}`);

  if (size2019 === 0 || size2020 === 0) {
    console.log("Missing data for one or both periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Create median composites
  const img2019 = col2019.median();
  const img2020 = col2020.median();

  // Check valid pixel counts
  const count2019 = await img2019.select('NDSI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: fuji,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDSI').getInfo();

  const count2020 = await img2020.select('NDSI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: fuji,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDSI').getInfo();

  console.log(`2019 Valid pixels: ${count2019}`);
  console.log(`2020 Valid pixels: ${count2020}`);

  if (count2019 === 0 || count2020 === 0) {
    console.log("No valid pixels after cloud masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate mean NDSI
  const ndsi2019 = await img2019.select('NDSI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: fuji,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDSI').getInfo();

  const ndsi2020 = await img2020.select('NDSI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: fuji,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDSI').getInfo();

  console.log(`2019 Mean NDSI: ${ndsi2019?.toFixed(3)}`);
  console.log(`2020 Mean NDSI: ${ndsi2020?.toFixed(3)}`);

  // Validate results
  if (ndsi2019 === null || ndsi2020 === null || 
      isNaN(ndsi2019) || isNaN(ndsi2020) ||
      ndsi2019 < -1 || ndsi2019 > 1 || ndsi2020 < -1 || ndsi2020 > 1) {
    console.log("Invalid NDSI values.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare and answer
  if (ndsi2020 < ndsi2019) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
